import{a as r}from"./chunk-2JSIA3BV.js";import{a as e}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var t=e(r,["Choisissez o\xF9 garder votre travail","Vous avez d\xE9j\xE0 un dossier Grading Studio ? Choisissez-le et votre travail revient.","Pas maintenant","La barre lat\xE9rale continue d’afficher \xAB Non sauvegard\xE9 \xBB tant qu’aucun dossier n’est choisi. Cliquez dessus quand vous voulez.","Votre travail n’est pas sauvegard\xE9","Cr\xE9er un fichier \xE0 emporter","Pour l’instant, votre correction existe seulement dans ce navigateur, et effacer les donn\xE9es du navigateur la supprimerait. Choisissez une fois un dossier sur cet ordinateur. Chaque enregistrement ira aussi l\xE0, avec une copie de chaque jour pour revenir en arri\xE8re. Rien n’est envoy\xE9 en ligne.","Le travail a chang\xE9 dans une autre fen\xEAtre pendant que ceci \xE9tait ouvert, il y a donc un nouveau choix \xE0 faire. Rien n’a encore \xE9t\xE9 import\xE9.","Ces \xE9l\xE9ments ont chang\xE9 \xE0 la fois ici et dans le fichier. Choisissez celui que vous voulez pour chacun.","Les commentaires enregistr\xE9s de l’autre ordinateur s’ajoutent aux v\xF4tres","Importation de votre travail…","Modifications de t\xE9l\xE9chargements que vous avez ici",{one:"{n} \xE9l\xE8ve arrive depuis le fichier",other:"{n} \xE9l\xE8ves arrivent depuis le fichier"},{one:"{n} exemple arrive ou change",other:"{n} exemples arrivent ou changent"},{one:"{n} fichier change : fichiers en retard, lectures ou modifications Word",other:"{n} fichiers changent : fichiers en retard, lectures ou modifications Word"},"\xC7a n’a pas abouti. Votre travail est en s\xE9curit\xE9, et une copie de s\xE9curit\xE9 a \xE9t\xE9 faite avant : Restaurer est ci-dessous si quelque chose semble faux.","Dans le fichier","Ce navigateur n’a plus de place, donc \xE7a n’a pas abouti. Vos annotations et notes ici n’ont pas \xE9t\xE9 remplac\xE9es. Lib\xE9rez de l’espace disque et r\xE9essayez.","Importer","Oubli\xE9","Oubli\xE9 sur l’autre ordinateur, donc retir\xE9 ici aussi","Reste oubli\xE9",{one:"{n} modification de classes, s\xE9quences ou listes",other:"{n} modifications de classes, s\xE9quences ou listes"},"Cr\xE9\xE9 {when}",{one:"{n} nouveau t\xE9l\xE9chargement",other:"{n} nouveaux t\xE9l\xE9chargements"},"Rien \xE0 importer : ce qui est ici contient d\xE9j\xE0 tout ce qu’il y a dans ce fichier.","Grilles ou r\xE9glages que vous n’avez pas encore ici",{one:"{n} le\xE7on, fichier ou r\xE9glage que votre pr\xE9paration ici n’a pas",other:"{n} le\xE7ons, fichiers ou r\xE9glages que votre pr\xE9paration ici n’a pas"},"Votre pr\xE9paration arrive, avec ses s\xE9quences, son emploi du temps et ses fichiers. Liez \xE0 nouveau son dossier si vous en utilisez un.","Ce navigateur manque peut-\xEAtre de place : il faut environ {need} et il reste environ {room}.","Une copie de s\xE9curit\xE9 de l’\xE9tat actuel est faite d’abord, donc vous pourrez annuler ci-dessous.",{one:"{n} t\xE9l\xE9chargement n’a rien \xE0 importer.",other:"{n} t\xE9l\xE9chargements n’ont rien \xE0 importer."},"Ressources de l’\xE9tablissement ajout\xE9es ou modifi\xE9es sur l’autre ordinateur",{one:"{n} r\xE9glage arrive depuis le fichier",other:"{n} r\xE9glages arrivent depuis le fichier"},"Le petit espace de ce navigateur pour les listes et les r\xE9glages est plein, donc \xE7a n’a pas abouti. Vos annotations et notes ici n’ont pas \xE9t\xE9 remplac\xE9es.",{one:"{n} \xE9l\xE8ve reste inchang\xE9 ici, car cette copie est plus r\xE9cente",other:"{n} \xE9l\xE8ves restent inchang\xE9s ici, car cette copie est plus r\xE9cente"},{one:"{n} \xE9l\xE8ve",other:"{n} \xE9l\xE8ves"},"Exporter ce que j’ai","Le navigateur n’a pas pu les stocker, souvent parce que l’ordinateur manque d’espace. Gardez cette fen\xEAtre ouverte, lib\xE9rez de l’espace et appuyez sur R\xE9essayer.","Vos derni\xE8res annotations et notes NE sont PAS enregistr\xE9es.","Enregistr\xE9. Votre travail est de nouveau en s\xE9curit\xE9.","Vos derni\xE8res annotations et notes ne sont enregistr\xE9es qu’en partie, dans la petite copie rapide de ce navigateur.","R\xE9essayer","Importer du travail","Tapez la phrase secr\xE8te de {name}. Tout le fichier est v\xE9rifi\xE9 avant que quoi que ce soit change ici.","Vous corrigez sur un autre ordinateur, ou vous passez \xE0 un nouveau ? Cr\xE9ez ici un fichier \xE0 emporter et importez-le l\xE0-bas. Pareil pour le retour.","Emporter votre travail","Ceci est l’exemple, donc il n’y a encore rien \xE0 vous \xE0 emporter.","Un fichier","Un \xE9l\xE8ve (la correction anonyme est activ\xE9e)","Le r\xE9cup\xE9rer","Modifi\xE9 {when}","Choisissez d’abord une version pour chacun.","\xE0 un moment ant\xE9rieur","Ni note, ni appr\xE9ciation, ni annotation",{one:"{file} : {n} annotation",other:"{file} : {n} annotations"},"Dans votre dossier","{file} va \xE0 {key}","Ce t\xE9l\xE9chargement a \xE9t\xE9 oubli\xE9, mais une copie contient du travail fait apr\xE8s.","Sur cet ordinateur","Elles diff\xE8rent entre ce navigateur et votre dossier, donc rien n’a \xE9t\xE9 choisi \xE0 votre place. En attendant votre d\xE9cision, chaque endroit garde la sienne.","D\xE9cider plus tard","Le laisser oubli\xE9","Corrig\xE9 {v}","Prendre la plus r\xE9cente pour chacun","Sans classe","Rien de configur\xE9","Rien ici","D\xE9sactiv\xE9","Utiliser mes choix","Activ\xE9","Un fichier va \xE0 un \xE9l\xE8ve","Points : {v}","Points, sur {n}","Ces deux copies n’ont pas les m\xEAmes crit\xE8res de grille, donc chacune affiche les siens.","Grille : {list}",{one:"Grille \xE0 {n} crit\xE8re",other:"Grille \xE0 {n} crit\xE8res"},"Les notes restent enregistr\xE9es dans les deux cas. Les totaux et pourcentages suivent celle que vous choisissez.","Feuille de notes : {v}","Deux versions au choix","V\xE9rification du fichier…","V\xE9rification du fichier… {n} sur {of}","Fermer","D\xE9cider","Fait","Drives partag\xE9s","Dernier dossier","Mon Drive","Partag\xE9s avec moi","Ce fichier est ab\xEEm\xE9, ou il a \xE9t\xE9 modifi\xE9 depuis sa cr\xE9ation, donc on ne peut pas s’y fier. Rien n’a chang\xE9 ici. Cr\xE9ez-en un nouveau si vous pouvez.","Ce fichier a \xE9t\xE9 cr\xE9\xE9 par une version plus r\xE9cente de Grading Studio. Rien n’a chang\xE9 ici. Rechargez cette page pour avoir la version la plus r\xE9cente, puis r\xE9essayez.","Ce n’est pas une sauvegarde de Grading Studio.","Ce n’est pas un fichier \xE0 emporter de Grading Studio.","Cette phrase secr\xE8te n’ouvre pas ce fichier. V\xE9rifiez-la et r\xE9essayez. Si vous en \xEAtes s\xFBr, le fichier est peut-\xEAtre ab\xEEm\xE9. Rien n’a chang\xE9 ici.","Choisissez une fois un dossier sur cet ordinateur, et chaque enregistrement y va en plus de ce navigateur, avec une copie de chaque jour pour revenir en arri\xE8re. Choisissez un endroit priv\xE9 : il contient des travaux d’\xE9l\xE8ves. Quand Chrome le demande, choisissez \xAB Autoriser \xE0 chaque visite \xBB. Si vous avez d\xE9j\xE0 un dossier Grading Studio, choisissez-le et votre travail revient.","Tout a \xE9t\xE9 r\xE9cup\xE9r\xE9 depuis votre dossier.","Ce dossier n’a pas pu \xEAtre utilis\xE9. Essayez-en un autre.",{one:"Du travail plus r\xE9cent est arriv\xE9 de votre dossier pour {n} \xE9l\xE8ve.",other:"Du travail plus r\xE9cent est arriv\xE9 de votre dossier pour {n} \xE9l\xE8ves."},"Choisir un dossier…","Fait. Votre travail s’enregistre maintenant aussi dans \xAB {name} \xBB.","C’est dans un dossier nomm\xE9 \xAB {root} \xBB \xE0 l’int\xE9rieur de \xAB {name} \xBB.","Une copie de vos copies, annotations, notes, appr\xE9ciations, listes et grilles est gard\xE9e ici, sans bouton d’enregistrement \xE0 retenir. Si ce navigateur est un jour effac\xE9, liez de nouveau le dossier et tout revient.","Certains fichiers list\xE9s par votre dossier n’y sont plus ou sont ab\xEEm\xE9s, donc ils n’ont pas pu \xEAtre r\xE9cup\xE9r\xE9s. Concern\xE9 : {list}. Vos annotations, notes et appr\xE9ciations sont toutes l\xE0. Pour r\xE9cup\xE9rer les copies, d\xE9posez \xE0 nouveau le m\xEAme t\xE9l\xE9chargement.","Utiliser un autre dossier…","Du travail plus r\xE9cent est arriv\xE9 de votre dossier, donc ce t\xE9l\xE9chargement a \xE9t\xE9 rouvert.","Ne plus utiliser ce dossier","Ne plus l’utiliser","Ne plus enregistrer dans \xAB {name} \xBB ?","Ce qui est d\xE9j\xE0 dans le dossier y reste. Rien n’y est supprim\xE9. Votre travail continue dans ce navigateur, sans deuxi\xE8me copie.","L’enregistrement dans un dossier est arr\xEAt\xE9. Les fichiers du dossier sont toujours l\xE0.","Pour tout remettre comme c’\xE9tait alors :","Un devoir","Cette copie n’a pas pu \xEAtre lue. Si votre dossier est sur un disque d\xE9branch\xE9, rebranchez-le et r\xE9essayez.",{one:"le travail de {n} \xE9l\xE8ve diff\xE8re",other:"le travail de {n} \xE9l\xE8ves diff\xE8re"},"\xAB {name} \xBB est revenu \xE0 son \xE9tat du {when}.","L’op\xE9ration n’a pas abouti : rien n’a \xE9t\xE9 restaur\xE9.","L’\xE9tat de chaque devoir le {when} :","Voir","{n} not\xE9es","Aucun des devoirs pr\xE9sents dans ce navigateur n’\xE9tait dans cette copie.","{n} sur {of} not\xE9es","Restaurer ce devoir","Lecture de cette copie…","Cet ordinateur manque de place : rien n’a \xE9t\xE9 restaur\xE9.","Identique \xE0 aujourd’hui","ses r\xE9glages diff\xE8rent","Alors {then}, maintenant {now}","Impossible d’annuler ici. La copie faite juste avant la restauration est sur cette page.","Annul\xE9. \xAB {name} \xBB est comme avant.","Le dossier garde une copie de chaque jour, et une avant toute grosse op\xE9ration. Revenir en arri\xE8re remet vos annotations, notes, appr\xE9ciations, fichiers en retard, lectures, listes et r\xE9glages comme ils \xE9taient alors. Les copies restent.","Copie du jour","\xC7a n’a pas abouti. Votre travail est peut-\xEAtre en partie revenu : utilisez Restaurer sur la copie de s\xE9curit\xE9 la plus r\xE9cente, ci-dessous.","Retour","Revenir en arri\xE8re","Liez un dossier et il gardera une copie de chaque jour pour revenir en arri\xE8re.","Pas encore de copie dans le dossier. La premi\xE8re est faite aujourd’hui.","Revenir \xE0 cette copie du {when} ?","Vos annotations, notes, appr\xE9ciations, fichiers en retard, lectures, listes et r\xE9glages reviennent comme ils \xE9taient alors, dans ce navigateur et dans le dossier. Les copies restent. Une copie de l’\xE9tat actuel est faite d’abord, donc c’est annulable.","L’ouvrir","Pr\xE9paration de votre travail…","Pr\xE9paration de votre travail… {n} sur environ {of}","Correction anonyme","Rep\xE8res sur les fichiers nouveaux et modifi\xE9s","Extraits vid\xE9o","Classe","Lien Google Drive","Travail de groupe","\xC9clairage","Fichiers d\xE9plac\xE9s","Un r\xE9glage","Cases de correction rapide","Les lectures que voit chaque \xE9l\xE8ve","Fichiers retir\xE9s et remplac\xE9s","Rendu aux \xE9l\xE8ves","Vos r\xE9ponses sur les pages scann\xE9es","Configurer la grille","Caches et codes de partage","Vid\xE9os remises \xE0 l’endroit","Phrase secr\xE8te","Encore une fois, pour \xEAtre s\xFBr","Choisissez une phrase secr\xE8te de quelques mots. Si vous l’oubliez, personne ne pourra ouvrir ce fichier, vous non plus, mais votre travail ici n’est pas touch\xE9. Gardez quand m\xEAme le fichier dans un endroit priv\xE9.","Les deux ne correspondent pas.","Utilisez au moins 8 caract\xE8res. Quelques mots ordinaires conviennent bien.","Reconnecter","Fait. Rechargement…","Retirer de cet ordinateur","Votre dernier fichier \xE0 emporter a \xE9t\xE9 cr\xE9\xE9 {when}, apr\xE8s votre derni\xE8re modification.","Retir\xE9 de cet ordinateur. Rechargement…","Tout n’a pas pu \xEAtre retir\xE9. Fermez les autres fen\xEAtres de Grading Studio et r\xE9essayez.","Votre dossier li\xE9 \xAB {name} \xBB n’est pas touch\xE9 : ses fichiers restent o\xF9 ils sont, et ce navigateur cesse d’y enregistrer.","Garder","Vous n’avez pas cr\xE9\xE9 de fichier \xE0 emporter depuis ce navigateur, donc ce qui a \xE9t\xE9 fait ici n’existe peut-\xEAtre nulle part ailleurs.",{one:"{n} t\xE9l\xE9chargement a des modifications depuis votre dernier fichier \xE0 emporter ({when}). Ces modifications ne sont pas dans ce fichier.",other:"{n} t\xE9l\xE9chargements ont des modifications depuis votre dernier fichier \xE0 emporter ({when}). Ces modifications ne sont pas dans ce fichier."},"La pr\xE9paration n’est pas touch\xE9e. C’est irr\xE9versible.",{one:"Ceci retire tout le travail des \xE9l\xE8ves de ce navigateur : {n} t\xE9l\xE9chargement avec ses copies, annotations, notes et appr\xE9ciations, plus les listes, s\xE9quences, grilles, fichiers en retard, lectures, modifications Word, ressources de l’\xE9tablissement, exemples et copies de s\xE9curit\xE9.",other:"Ceci retire tout le travail des \xE9l\xE8ves de ce navigateur : {n} t\xE9l\xE9chargements avec leurs copies, annotations, notes et appr\xE9ciations, plus les listes, s\xE9quences, grilles, fichiers en retard, lectures, modifications Word, ressources de l’\xE9tablissement, exemples et copies de s\xE9curit\xE9."},"Tapez RETIRER pour continuer","RETIRER","Une copie compl\xE8te de votre travail est gard\xE9e dans ce navigateur avant toute op\xE9ration risqu\xE9e, comme importer du travail, revenir en arri\xE8re ou commencer une nouvelle ann\xE9e. Les trois plus r\xE9centes sont gard\xE9es. Les copies d’\xE9l\xE8ves n’y sont pas, car elles ne changent jamais.","Faite par la version actuelle de l’app","Copies de s\xE9curit\xE9","Pas encore de copie de s\xE9curit\xE9.","Restaurer","Restaurer la copie de s\xE9curit\xE9 du {when} ?","Tout revient comme c’\xE9tait alors, et ce qui a \xE9t\xE9 ajout\xE9 depuis dispara\xEEt. Les copies d’\xE9l\xE8ves restent, donc un t\xE9l\xE9chargement ouvert depuis garde sa ligne sans annotations. L’\xE9tat actuel est gard\xE9 d’abord, donc c’est annulable.","Arr\xEAter","Emporter mon travail","Cr\xE9e un fichier prot\xE9g\xE9 avec tout ce qu’il faut pour corriger sur un autre ordinateur : fichiers des \xE9l\xE8ves, annotations, notes, appr\xE9ciations, listes, grilles, lectures, modifications Word, fichiers ajout\xE9s et bons exemples. Votre pr\xE9paration suit aussi : le\xE7ons, s\xE9quences, emploi du temps et leurs fichiers.","Fait : {name} ({size}). Ouvrez Grading Studio sur l’autre ordinateur et utilisez Importer du travail. Pareil pour le retour.","Les copies ne sont pas dans le fichier pour : {list}. Seules les annotations et les notes sont parties. Il vous faudra ces t\xE9l\xE9chargements sur l’autre ordinateur.","Le fichier n’a pas \xE9t\xE9 termin\xE9, il est donc inutilisable. Votre travail ici n’a rien. R\xE9essayez \xE0 un endroit avec plus de place.","Travail Grading Studio {day}","Cr\xE9er le fichier","Travail Grading Studio","Pas de copies pour : {list}. Ce navigateur ne les garde pas, donc seules les annotations et les notes seront dans le fichier. Pour emporter aussi les copies, d\xE9posez d’abord ici chacun de ces t\xE9l\xE9chargements.","Le fichier n’a pas pu \xEAtre \xE9crit l\xE0. Essayez un autre endroit.","Seulement dans ce navigateur. \xAB {name} \xBB attend un clic pour se reconnecter","Chrome a besoin de votre accord pour r\xE9utiliser le dossier. Choisissez \xAB Autoriser \xE0 chaque visite \xBB et il ne demandera plus","V\xE9rification de l’emplacement de votre travail…",{one:"{n} chose \xE0 d\xE9cider pour votre dossier",other:"{n} choses \xE0 d\xE9cider pour votre dossier"},"Deux versions entre lesquelles choisir","Sauvegard\xE9 dans votre Google Drive","Chaque modification va aussi dans le dossier cach\xE9 de Grading Studio dans votre Google Drive","Seulement dans ce navigateur. Le disque de “{name}” est plein","{text}.","{text}. {tip}.","Seulement dans ce navigateur. Impossible d’acc\xE9der \xE0 “{name}”","Il se remettra \xE0 jour tout seul d\xE8s que le dossier sera de retour","Non sauvegard\xE9. Seulement dans ce navigateur","Effacer les donn\xE9es de ce navigateur effacerait votre travail. Ce navigateur ne peut pas enregistrer dans un dossier, alors cr\xE9ez un fichier \xE0 emporter quand vous avez fini de corriger","Effacer les donn\xE9es de ce navigateur effacerait votre travail. Choisissez un dossier et chaque sauvegarde y ira aussi","Dans ce navigateur et dans votre dossier “{name}”","Chaque enregistrement va aux deux endroits. Dernier enregistrement dans le dossier \xE0 {time}","Chaque enregistrement va aux deux endroits","Seulement dans ce navigateur. Le navigateur manque de place, donc “{name}” ne peut pas se mettre \xE0 jour","Exemple, gard\xE9 seulement pendant votre visite","Rien ici n’est votre travail. Quittez l’exemple et il est effac\xE9","Enregistrement dans votre dossier “{name}”…","Enregistrement dans votre dossier “{name}” ({prog})…","Votre travail est d\xE9j\xE0 dans ce navigateur","O\xF9 votre travail est enregistr\xE9","l’ann\xE9e du fichier","Vos classes continuent dans une nouvelle ann\xE9e avec des listes de classe vides. D’abord, tout ce qui concerne cette ann\xE9e part dans un fichier prot\xE9g\xE9, et le fichier est v\xE9rifi\xE9 avant que quoi que ce soit soit effac\xE9 ici.","Archiv\xE9es : {list}",{one:"{n} classe, avec ses s\xE9quences et ses cartes de devoir. Chaque carte garde sa grille et ses cases de correction rapide. Ni copies, ni notes, ni appr\xE9ciations.",other:"{n} classes, avec leurs s\xE9quences et leurs cartes de devoir. Chaque carte garde sa grille et ses cases de correction rapide. Ni copies, ni notes, ni appr\xE9ciations."},"Ce qui est repris","La relecture du fichier ne correspond pas \xE0 votre travail ici, donc on ne peut pas s’y fier. Rien n’a \xE9t\xE9 modifi\xE9 ici. R\xE9essayez \xE0 un endroit avec plus de place.","Dates de rendu et dates de p\xE9riode, un an plus tard","Le fichier n’a pas \xE9t\xE9 termin\xE9, donc rien n’a \xE9t\xE9 modifi\xE9 ici. R\xE9essayez \xE0 un endroit avec plus de place.","L’ann\xE9e que vous cl\xF4turez","Enregistrer le fichier et commencer la nouvelle ann\xE9e","(d’apr\xE8s les dates de vos p\xE9riodes)","Ann\xE9e scolaire","{year} dans {file}, {when}","Ann\xE9e Grading Studio",{one:"{n} lot de copies part dans le fichier et quitte ce navigateur.",other:"{n} lots de copies partent dans le fichier et quittent ce navigateur."},"Donnez un nom aux deux ann\xE9es, par exemple 2025–26 et 2026–27.","Cette ann\xE9e : {year}","Ouvrir une ann\xE9e archiv\xE9e","\xC7a n’a pas abouti. {now} est en s\xE9curit\xE9 dans {file}, et une copie de s\xE9curit\xE9 a \xE9t\xE9 faite avant : Restaurer est ci-dessous. Rechargez avant de faire quoi que ce soit d’autre.","L’ouvrir met cette ann\xE9e \xE0 la place de ce qui est ici maintenant. D’abord, {now} est enregistr\xE9 dans son propre fichier avec la m\xEAme phrase secr\xE8te, et v\xE9rifi\xE9, pour que vous puissiez revenir de la m\xEAme fa\xE7on.","Ce navigateur cesse d’enregistrer dans le dossier \xAB {name} \xBB, qui garde l’ann\xE9e en cours.","Enregistrer {now} et ouvrir {year}","Ouvrir {year}","La pr\xE9paration ne change pas : les le\xE7ons de l’an dernier sont d\xE9j\xE0 dans Le\xE7ons pass\xE9es.",{one:"Le fichier contient {n} lot de copies, avec ses classes, listes de classe, annotations et notes, cr\xE9\xE9 {when}.",other:"Le fichier contient {n} lots de copies, avec leurs classes, listes de classe, annotations et notes, cr\xE9\xE9 {when}."},"Choisissez une phrase secr\xE8te de quelques mots. Personne ne peut ouvrir le fichier sans elle, vous non plus, alors notez-la dans un endroit s\xFBr.","S\xE9quences de pr\xE9paration et semestre, un an plus tard. Les le\xE7ons de cette ann\xE9e passent dans Le\xE7ons pass\xE9es, pr\xEAtes \xE0 \xEAtre r\xE9utilis\xE9es.","Prot\xE9ger le fichier","Listes de classe, seulement pour les classes qui gardent les m\xEAmes \xE9l\xE8ves. Sinon, elles restent vides et la liste de suivi est effac\xE9e.","La nouvelle ann\xE9e doit avoir un nom diff\xE9rent de celle que vous cl\xF4turez.","Enregistrement de {year} dans un fichier…","Commencer une nouvelle ann\xE9e scolaire","La nouvelle ann\xE9e n’a pas fini de se mettre en place. Tout ce qui concerne {year} est en s\xE9curit\xE9 dans {file}, et une copie de s\xE9curit\xE9 a \xE9t\xE9 faite avant : Restaurer est ci-dessous si quelque chose semble faux.","{year} a commenc\xE9","Vos classes, s\xE9quences et cartes de devoir sont pr\xEAtes. Collez les \xE9l\xE8ves de chaque classe dans son onglet \xC9l\xE8ves si les listes sont vides. Tout ce qui concerne {from} est dans {file} ({size}), v\xE9rifi\xE9. Gardez-le dans un endroit s\xFBr avec sa phrase secr\xE8te. Ouvrir une ann\xE9e archiv\xE9e le restaure.","D\xE9marrage de {year}…","Vos r\xE9glages, bar\xE8me, grilles enregistr\xE9es et banque de commentaires restent tels quels.","La nouvelle ann\xE9e"],null);export{t as default};
